def matches_pattern(filename, pattern):
    if len(filename) != len(pattern):
        return False
    for f, p in zip(filename, pattern):
        if p != '?' and f != p:
            return False
    return True

def find_pattern(filenames, to_delete):
    if not to_delete:
        return "No"

    pattern = list(filenames[to_delete[0] - 1])

    for index in to_delete[1:]:
        current_filename = filenames[index - 1]
        for i in range(len(pattern)):
            if pattern[i] != '?' and pattern[i] != current_filename[i]:
                pattern[i] = '?'

    for i, filename in enumerate(filenames):
        if (i + 1) in to_delete:
            if not matches_pattern(filename, pattern):
                return "No"
        else:
            if matches_pattern(filename, pattern):
                return "No"

    return "Yes\n" + "".join(pattern)

